go.example/example.go:
package example

import "example.com/ormexample/model"

func Load() *model.ProductModel {
	return model.Product().GtPrice(1).OrBrandSeq(2).AndLtPrice(3).OrderByPriceDescAndSeqAsc().NewScore(1).Relation(model.Brand().MatchBrandSeqWithSeq().AliasOwner())
}

func Score(p *model.ProductModel) any { return p.GetScore() }

func Owner(p *model.ProductModel) (any, error) { return p.GetOwner() }

typescript.example/example.ts:
import { Brand, Product } from '../model/models.js';

const row = new Product().gtPrice(1).orBrandSeq(2).andLtPrice(3).orderByPriceDescAndSeqAsc().newScore(1).relation(new Brand().matchBrandSeqWithSeq().aliasOwner());
row.getScore();
row.getOwner();

rust.example/example.rs:
mod own { include!("../model/orm_model.rs"); }
use own::{Brand, Product};

fn run() {
    let row = Product::new().gt_price(1).or_brand_seq(2).and_lt_price(3).order_by_price_desc_and_seq_asc().new_score(1).relation(Brand::new().match_brand_seq_with_seq().alias_owner());
    let _ = row.get_score();
    let _ = row.get_owner();
}

